"""Compara previsões com anotações editoriais; nunca altera expectativas."""
from pathlib import Path
import json,collections,hashlib
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'data/acervo-ampliado'
def load(name):return json.loads((OUT/name).read_text(encoding='utf-8-sig'))
def save(name,d):(OUT/name).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def main():
 old={r['source_id']:r for r in load('catalogo-global.json')['questions']};new={r['source_id']:r for r in load('catalogo-global-v2.json')['questions']};gold=load('classification-golden-set.json')['questions'];results=[]
 for g in gold:
  e=g['expected'];r=new[g['source_id']]
  checks={'primary_module':r['primary_module']==e['primary_module'],'secondary_modules':set(r['secondary_modules'])==set(e['secondary_modules']),'primary_concept':r['primary_concept']==e['primary_concept'],'semantic_family':r['semantic_family']==e['semantic_family'],'probable_type':r['probable_type']==e['probable_type'],'required_types':set(e['probable_types'])<=set(r['probable_types']),'unclassified_reason':r['unclassified_reason']==e['unclassified_reason']}
  results.append({'source_id':g['source_id'],'stratum':g['sample_stratum'],'checks':checks,'passed':all(checks.values()),'expected':e,'actual':{k:r[k] for k in ['primary_module','secondary_modules','primary_concept','semantic_family','probable_type','probable_types','unclassified_reason']},'v1_correct_primary':old[g['source_id']]['primary_module']==e['primary_module'],'review_rationale':g['review']['rationale']})
 report={'golden_size':len(gold),'passed':sum(r['passed'] for r in results),'failed':sum(not r['passed'] for r in results),'check_counts':{k:sum(r['checks'][k] for r in results) for k in results[0]['checks']},'v1_correct_primary':sum(r['v1_correct_primary'] for r in results),'v2_correct_primary':sum(r['checks']['primary_module'] for r in results),'required_regressions':[r for r in results if r['source_id'] in ['Q4148970','Q4148977','Q4150424','Q4151541']],'cases':results,'limits':'Amostra editorial dirigida, usada para ajustar regras. Concordância de regressão, não estimativa imparcial da precisão nos 9.791 itens.'};save('classification-regressions.json',report)
 modules=load('cruzamento-35-temas.json')['modulos'];audits=[]
 for m in modules:
  mid=m['modulo'];rows=[]
  for version,catalog in [('V1',old),('V2',new)]:
   for confidence in ['HIGH','MEDIUM','LOW']:
    evaluated=[r for r in results if catalog[r['source_id']]['primary_module']==mid and catalog[r['source_id']]['theme_classification_confidence']==confidence]
    correct=sum(r['expected']['primary_module']==mid for r in evaluated)
    # This identifies sampled false positives; it does not estimate unobserved errors.
    rows.append({'version':version,'confidence':confidence,'sampled':len(evaluated),'correct_primary':correct,'wrong_primary':len(evaluated)-correct,'approximate_sample_precision':correct/len(evaluated) if evaluated else None})
  expected=[r for r in results if r['expected']['primary_module']==mid]
  audits.append({'module':mid,'title':m['titulo'],'strata':rows,'golden_expected_examples':len(expected),'v1_sampled_false_negatives':sum(old[r['source_id']]['primary_module']!=mid for r in expected),'v2_sampled_false_negatives':sum(new[r['source_id']]['primary_module']!=mid for r in expected),'secondary_reviewed':sum(mid in r['expected']['secondary_modules'] for r in results),'false_positive_ids_v1':[r['source_id'] for r in results if old[r['source_id']]['primary_module']==mid and r['expected']['primary_module']!=mid]})
 save('auditoria-classificacao-v2.json',{'modules':audits,'sampling':'150 estratos V1/UNCLASSIFIED mais 3 casos de H01/H02, seed 20261006; quatro imagens inspecionadas. Estratos vazios não têm precisão estimada.','golden_expected_modules':len({g['expected']['primary_module'] for g in gold if g['expected']['primary_module']}),'not_holdout':True})
 summary=load('resumo-global-v2.json');unclassified=load('unclassified-analysis.json');original878=[r for r in unclassified['questions'] if r['v1_unclassified']];causes=dict(collections.Counter(r['unclassified_reason'] or 'RECLASSIFIED' for r in original878))
 structural=[]
 def check(name,value):structural.append({'check':name,'passed':bool(value)})
 check('IDs V1/V2 identical',set(old)==set(new) and len(new)==9791)
 check('V1 unchanged',hashlib.sha256((OUT/'catalogo-global.json').read_bytes()).hexdigest()==load('catalogo-global-v2.json')['v1_sha256'])
 preserve=['statement','source_id','source_file','source_reference','current_theme','current_subthemes','prior_topics','alternatives_count','image_references','html_image_count','source_answer_available']
 check('recovery fields unchanged',all(all(old[sid][k]==new[sid][k] for k in preserve) for sid in old))
 check('answers all unresolved',all(r['answer_status']=='UNRESOLVED' for r in new.values()))
 check('all 878 formerly unclassified analyzed',len(original878)==878)
 check('all 35 modules have editorial golden examples',len({g['expected']['primary_module'] for g in gold if g['expected']['primary_module']})==35)
 check('all regression fields match',report['failed']==0)
 check('no strong family claimed for unseen essential imagery',all(r['family_status']!='REVIEWED_IMAGE_CONTEXT' or r['image_classification_basis']=='AGENT_VISUAL_OBSERVATION' for r in new.values()))
 check('all primary-less items have reason',all(r['unclassified_reason'] for r in new.values() if not r['primary_module']))
 check('source lot hashes unchanged',all(hashlib.sha256(Path(f['path']).read_bytes()).hexdigest()==f['sha256'] for f in load('resumo-global.json')['SOURCE_FILES']))
 taxonomy=load('taxonomia-conceitos-v2.json');nodes=taxonomy['definitions']+taxonomy['parent_nodes'];parents={n['concept']:n['parent'] for n in nodes}
 check('taxonomy IDs unique',len(parents)==len(nodes))
 acyclic=True
 for node in parents:
  visited=set();cur=node
  while cur in parents:
   if cur in visited:acyclic=False;break
   visited.add(cur);cur=parents[cur]
 check('taxonomy acyclic',acyclic)
 check('all families registered',all(not r['semantic_family'] or r['semantic_family'] in parents for r in new.values()))
 validation={'passed':sum(c['passed'] for c in structural),'failed':sum(not c['passed'] for c in structural),'checks':structural};save('validacao-classificacao-v2.json',validation)
 lines=['# Auditoria da classificação V2','', '**V2 produzida, com 9.791 IDs preservados.** A V1 continua intacta. A classificação permanece preliminar; não foram resolvidos gabaritos, publicados itens ou alterado o acervo externo. S01 não foi iniciado.','', '## Golden set e regressões','', f"O conjunto tem **{len(gold)} questões reais**, expectativas editoriais anotadas após leitura de enunciados e alternativas, com exemplos dos 35 módulos e casos sem módulo. Quatro imagens foram abertas e inspecionadas: Q4148970, Q4148977, Q4150424 e Q4027618. Outros itens visuais têm revisão temática baseada no texto e dependências explícitas, sem alegar interpretação de figuras não vistas.",'', f"Resultados: **{report['passed']} casos passaram / {report['failed']} falharam**; V1 acertou o módulo principal em {report['v1_correct_primary']}/{len(gold)} casos e V2 em {report['v2_correct_primary']}/{len(gold)}. As checagens cobrem módulo principal, secundários, conceito, família, tipo principal, tipos requeridos e causa de ausência de módulo.",'', '**Limite decisivo:** o golden set foi usado no desenvolvimento das regras. Resultado perfeito nesse conjunto, se obtido, é concordância de regressão, não prova de 100% de precisão do catálogo. Não é holdout. A seleção privilegia enunciados curtos, poucos visuais e estratos da V1; foi completada com três casos dirigidos de H01/H02. Sem revisão humana independente.','', '## Comparação V1 → V2','', '| Indicador | Total |','|---|---:|']
 lines += [f'| {k} | {v} |' for k,v in summary.items() if isinstance(v,(int,bool))]
 lines += [f'| {k} | {v} |' for k,v in summary['V1_COMPARISON'].items()]
 lines += ['', 'A redução do número de módulos atribuídos é intencional: tópico anterior sozinho não escolhe um módulo, e assuntos de eletrônica sem módulo dedicado ficam MISSING_MODULE. Isso é mais conservador que manter falsos encaixes só para aumentar cobertura. Os conceitos reconhecidos continuam visíveis. Menções incidentais a motor/transformador deixam de gerar filas secundárias.','', '## Casos obrigatórios','', '| ID | V1 | V2 | Justificativa |','|---|---|---|---|']
 for r in report['required_regressions']:
  sid=r['source_id'];lines.append(f"| {sid} | {old[sid]['primary_module']} / {old[sid]['semantic_family']} | {new[sid]['primary_module']} / {new[sid]['semantic_family']} | {r['review_rationale']} |")
 lines += ['', 'Transistor identificado com confiança conceitual não cria um módulo curricular inexistente. Q4150424 recebe TRANSISTOR_IDENTIFICATION + MISSING_MODULE. E01 acolhe operação/velocidade de motores, incluindo reconhecimento de máquina assíncrona. Wheatstone entra em F02 como análise de circuito e M01 como reutilização na técnica de medição.','', '## As 878 questões originalmente sem módulo','', '| Resultado/causa preliminar | Total |','|---|---:|']
 lines += [f'| {k} | {v} |' for k,v in sorted(causes.items())]
 lines += ['', 'Cada ID tem causa e evidência em unclassified-analysis.json. CLASSIFIER_GAP não significa fora do currículo. IMAGE_REQUIRED é uma dependência, não INVALID. OUT_OF_CURRICULUM exige enquadramento explícito em assunto externo; não foi atribuído só porque uma regra falhou. MISSING_MODULE indica conceito técnico reconhecido sem espaço curricular natural nos 35 módulos atuais.','', '## Auditoria por módulo','', 'Acertos abaixo são apenas nos exemplos revisados. Foram auditados HIGH, MEDIUM e LOW da V1 quando existiam candidatos elegíveis; a divisão V2 permite ver estratos vazios, sem fabricar precisão. False negatives são itens cujo módulo esperado era diferente da previsão, dentro da amostra. Nenhum desses números estima exaustivamente as falhas do banco.','', '| Módulo | Esperados no golden | V1 HIGH corretos/amostrados | V2 HIGH corretos/amostrados | Falsos negativos V1/V2 |','|---|---:|---|---|---|']
 for a in audits:
  high=[next(s for s in a['strata'] if s['version']==v and s['confidence']=='HIGH') for v in ['V1','V2']]
  lines.append(f"| {a['module']} | {a['golden_expected_examples']} | {high[0]['correct_primary']}/{high[0]['sampled']} | {high[1]['correct_primary']}/{high[1]['sampled']} | {a['v1_sampled_false_negatives']}/{a['v2_sampled_false_negatives']} |")
 lines += ['', 'MEDIUM/LOW, secundários revistos e IDs de falsos positivos constam em auditoria-classificacao-v2.json. Zero amostras é ausência de estimativa, não zero erro. Um exemplo Dahlander e um eletropneumático são insuficientes para inferir a qualidade dos respectivos módulos.','', '## O que mudou no mecanismo','', 'Taxonomia com pais conceituais e mapeamento curricular separado da família; padrões de relações técnicas específicas e precedência contextual. Conceito explícito ou observação visual revisada domina assunto original; tópico anterior e alternativas só apoiam. Distratores não criam um conceito principal por votação. Intertravamento não é bloqueio hidráulico; circuito de potência não é cálculo de potência; testes de isolamento aplicados a motores/transformadores permanecem medições.','', 'HIGH exige quadro técnico explícito, especificidade e ausência de empate/visual essencial não inspecionado. Não equivale ao antigo score≥5. Confiança conceitual é separada da atribuição de módulo: um conceito pode ser reconhecido e continuar sem módulo. As regras são determinísticas auditáveis; não são compreensão semântica exaustiva por embeddings/LLM.','', 'Interação V2 usa critérios explícitos de decomposição, extração, unidades, múltiplas etapas, leitura de imagem, proposições, sequência e diagnóstico. HIGH requer riqueza de raciocínio, não presença de número. Reconhecimento simples pode permanecer questão normal. Os critérios são hipóteses de planejamento, não etapas prontas. TF_L2–TF_L5 são sugestões de profundidade, sem conversão ou inferência de gabarito.','', 'Inspeção: P0 para falhas estruturais/sinais de imagem faltante e normas críticas; P1 para empates, visuais não inspecionados, lacunas aparentes ou interação rica; P2 para classificação incerta; P3 para candidatos textuais fortes. Motivos da V1 permanecem em v1_inspection_reasons; classification_inspection_reasons é a leitura vigente.','', 'Variantes semânticas são grupos candidatos por conceito + estrutura da pergunta; isso encontra contas equivalentes com números/enunciados diferentes, mas não garante duplicidade. Não excluímos nenhuma questão. Questões da mesma família de habilidade não contam automaticamente como evidências independentes de domínio.','', '## Arquivos e reprodução','', '```powershell','python scripts/reclassificar-acervo-v2.py','python scripts/auditar-classificacao-v2.py','python -m unittest discover -s scripts -p "test_classificacao_v2.py" -v','```','', 'Não regenerar o golden set automaticamente após alterações no classificador; expectativas só mudam por revisão editorial documentada. anotar-golden-classificacao.py registra as anotações desta sessão sem chamar a inferência. As listas V1 não são sobrescritas.','', '- catalogo-global-v2.json, resumo-global-v2.json e por-modulo-v2/: previsões e filas.', '- taxonomia-conceitos-v2.json, familias-semanticas-v2.json e variantes-semanticas-v2.json: conceitos e agrupamentos.', '- unclassified-analysis.json: causas, incluindo todos os 878 IDs anteriores.', '- classification-golden-set.json e classification-regressions.json: expectativas e resultados por campo.', '- auditoria-classificacao-v2.json, validacao-classificacao-v2.json e observacoes-visuais-classificacao-v2.json: revisão e integridade.','', '## Antes de liberar produção de S01','', 'Os casos óbvios foram corrigidos e a regressão editorial foi executada. A V2 pode orientar seleção assistida por revisão; não deve publicar ou escolher conteúdo sozinha. Próxima verificação de qualidade: amostra cega, fora do golden set, com mais enunciados longos, imagens reais e normas; decidir como tratar os conceitos de eletrônica/instrumentação sem módulo. Reunir candidatos S01 de todas as forças, sem excluir itens CLASSIFIER_GAP ligados à segurança, e revisar um subconjunto antes de resolver. Não iniciar S01 completo automaticamente.','']
 (ROOT/'docs/auditoria-classificacao.md').write_text('\n'.join(lines),encoding='utf-8')
 print(json.dumps({'golden':report['golden_size'],'regressions_passed':report['passed'],'regressions_failed':report['failed'],'v1_correct_primary':report['v1_correct_primary'],'v2_correct_primary':report['v2_correct_primary'],'validation':validation['passed'],'validation_failed':validation['failed'],'original_878_causes':causes},indent=2))
 assert report['failed']==0 and validation['failed']==0
if __name__=='__main__':main()
